html:
{%- set R = frappe.get_attr("pos_next.api.receipt_print.invoice_meta_for_jinja")(doc) -%}
{%- set ES = frappe.get_attr("pos_next.api.receipt_print.einvoice_qr_payload_for_jinja")(doc.name) -%}
{%- set fmt = frappe.get_attr("pos_next.api.receipt_print.format_vn_amount") -%}
{%- set TX = frappe.get_attr("pos_next.api.receipt_print.receipt_totals_aux_for_print")(doc) -%}
<style>
	@page { size: 80mm auto; margin: 0mm; }
	body {
		font-family: 'DejaVu Sans', 'Arial', sans-serif;
		width: 80mm;
		max-width: 80mm;
		margin: 0 auto;
		padding: 8px 10px 12px;
		font-size: 10px;
		line-height: 1.35;
		color: #111;
	}
	.bold { font-weight: bold; }
	.center { text-align: center; }
	.store-name { font-size: 14px; font-weight: bold; margin-bottom: 4px; }
	.doc-title { font-size: 12px; font-weight: bold; margin: 10px 0 8px; letter-spacing: 0.02em; }
	.meta-row { display: table; width: 100%; margin-bottom: 8px; font-size: 9px; }
	.meta-left, .meta-right { display: table-cell; width: 50%; vertical-align: top; }
	.meta-right { text-align: right; padding-left: 6px; }
	.divider { border-top: 1px dashed #333; margin: 8px 0; }
	.cust-block { font-size: 9px; margin-bottom: 8px; line-height: 1.45; }
	table.items { width: 100%; border-collapse: collapse; font-size: 9px; margin-bottom: 6px; }
	table.items th { text-align: left; font-weight: bold; padding: 2px 0; border-bottom: 1px solid #000; }
	table.items th.r, table.items td.r { text-align: right; }
	table.items th:nth-child(2), table.items td:nth-child(2) { width: 10%; }
	table.items th:nth-child(3), table.items td:nth-child(3) { width: 22%; }
	table.items th:nth-child(4), table.items td:nth-child(4) { width: 22%; }
	table.items td { vertical-align: top; padding: 3px 0 2px; }
	tr.item-name td { font-weight: bold; padding-bottom: 0; border-bottom: none; }
	tr.item-line td { padding-top: 1px; font-size: 9px; }
	.totals { font-size: 10px; margin-top: 4px; }
	.totals .row { display: table; width: 100%; margin: 3px 0; }
	.totals .row > span:first-child { display: table-cell; text-align: left; width: 62%; }
	.totals .row > span:last-child { display: table-cell; text-align: right; width: 38%; }
	.totals .grand { font-weight: bold; font-size: 11px; border-top: 1px solid #000; padding-top: 6px; margin-top: 6px; }
	.pay-block { margin-top: 6px; font-size: 9px; }
	.loyalty { font-size: 8px; margin: 10px 0 6px; line-height: 1.4; border-top: 1px dashed #333; padding-top: 8px; }
	.einv-wrap { text-align: center; margin: 10px 0 8px; padding: 8px 0; border-top: 1px dashed #333; border-bottom: 1px dashed #333; }
	.einv-wrap .t { font-weight: bold; font-size: 10px; margin-bottom: 6px; }
	.einv-wrap img { width: 112px; height: 112px; display: block; margin: 0 auto; }
	.footer { text-align: center; margin-top: 10px; font-size: 9px; line-height: 1.45; }
	.warn-partial { color: #b30000; font-weight: bold; font-size: 9px; margin-top: 4px; }
	@media print {
		body { width: 80mm; max-width: 80mm; padding: 5mm 5mm 6mm; }
	}
</style>

<div class="center store-name">{{ R.receipt_company_display_name }}</div>
<div class="center" style="font-size:9px;line-height:1.4;">
	<div><span class="bold">Chi nhánh:</span> {{ R.receipt_branch_label }}</div>
	{% if R.receipt_company_address %}<div>{{ R.receipt_company_address }}</div>{% endif %}
	{% if R.receipt_company_phone %}<div><span class="bold">Số điện thoại:</span> {{ R.receipt_company_phone }}</div>{% endif %}
</div>

<div class="center doc-title">PHIẾU TÍNH TIỀN</div>

<div class="meta-row">
	<div class="meta-left">
		<div><span class="bold">Thời gian:</span> {{ R.receipt_print_datetime }}</div>
		<div><span class="bold">Mã HĐ:</span> {{ doc.name }}</div>
	</div>
	<div class="meta-right">
		<div><span class="bold">MSCH:</span> {% if R.receipt_msch %}{{ R.receipt_msch }}{% else %}—{% endif %}</div>
		<div><span class="bold">NV:</span> {{ R.receipt_salesperson }}</div>
	</div>
</div>

<div class="divider"></div>

<div class="cust-block">
	<div><span class="bold">Tên khách hàng:</span> {{ doc.customer_name or 'Khách lẻ' }}</div>
	<div><span class="bold">Số điện thoại:</span> {% if R.receipt_customer_phone %}{{ R.receipt_customer_phone }}{% else %}—{% endif %}</div>
</div>

{% if doc.status == "Partly Paid" or (doc.outstanding_amount and doc.outstanding_amount > 0 and doc.outstanding_amount < doc.grand_total) %}
<div class="warn-partial">Trạng thái: THANH TOÁN MỘT PHẦN</div>
{% endif %}

<table class="items">
	<thead>
		<tr>
			<th>Mặt hàng/giá</th>
			<th class="r">SL</th>
			<th class="r">KM</th>
			<th class="r">T.tiền</th>
		</tr>
	</thead>
	<tbody>
		{%- for item in doc.items -%}
		<tr class="item-name">
			<td colspan="4">{{ item.item_name }}</td>
		</tr>
		<tr class="item-line">
			<td>{{ fmt(item.price_list_rate or item.rate, 2) }}</td>
			<td class="r">{{ "%.0f"|format(item.qty or 0) }}</td>
			<td class="r">{{ fmt(item.discount_amount or 0, 2) }}</td>
			<td class="r">{{ fmt(item.amount or 0, 0) }}</td>
		</tr>
		{%- endfor -%}
	</tbody>
</table>

<div class="divider"></div>

<div class="totals">
	<div class="row"><span>Tổng tiền hàng</span><span>{{ fmt(doc.total or 0, 0) }}</span></div>
	<div class="row"><span>Chiết khấu</span><span>{{ fmt(TX.disc, 0) }}</span></div>
	<div class="row">
		<span>{{ TX.vat_lbl }}</span>
		<span>{{ fmt(TX.vat_amt, 0) }}</span>
	</div>
	<div class="row grand"><span>Tổng cần thanh toán</span><span>{{ fmt(doc.grand_total or 0, 0) }}</span></div>
</div>

{%- if doc.payments -%}
<div class="pay-block">
	{%- for payment in doc.payments -%}
	<div class="row" style="display:table;width:100%;margin:2px 0;font-size:9px;">
		<span style="display:table-cell;text-align:left;">{{ payment.mode_of_payment }}</span>
		<span style="display:table-cell;text-align:right;">{{ fmt(payment.amount or 0, 0) }}</span>
	</div>
	{%- endfor -%}
	{%- if doc.change_amount and doc.change_amount > 0 -%}
	<div class="row" style="display:table;width:100%;margin:4px 0 0;font-size:9px;">
		<span style="display:table-cell;text-align:left;" class="bold">Tiền thừa</span>
		<span style="display:table-cell;text-align:right;">{{ fmt(doc.change_amount, 0) }}</span>
	</div>
	{%- endif -%}
	{%- if doc.outstanding_amount and doc.outstanding_amount > 0 -%}
	<div class="row" style="display:table;width:100%;margin:4px 0;font-size:9px;color:#b30000;font-weight:bold;">
		<span style="display:table-cell;text-align:left;">Còn phải thu</span>
		<span style="display:table-cell;text-align:right;">{{ fmt(doc.outstanding_amount, 0) }}</span>
	</div>
	{%- endif -%}
</div>
{%- endif -%}

<div class="loyalty">
	Điểm tích lũy: Hóa đơn hiện tại được cộng {{ "%.0f"|format(R.receipt_loyalty_earned or 0) }} điểm; Tổng điểm sau hóa đơn là {{ "%.0f"|format(R.receipt_loyalty_balance or 0) }}.
</div>

{%- if ES and ES.qr_image_url -%}
<div class="einv-wrap">
	<div class="t">MÃ QR HÓA ĐƠN ĐIỆN TỬ</div>
	<div style="font-size:10px;line-height:1.35;margin:0 0 4px;text-align:center;">Quét QR để xuất hóa đơn điện tử</div>
	<div style="font-size:10px;line-height:1.35;margin:0 0 8px;text-align:center;">hoặc mở liên kết (trong 2 giờ):</div>
	<img src="{{ ES.qr_image_url }}" alt="QR HDDT" />
</div>
{%- endif -%}

<div class="footer">
	{% if R.receipt_company_phone %}<div>Số điện thoại cửa hàng — {{ R.receipt_company_phone }}</div>{% endif %}
	<div style="margin-top:6px;font-weight:bold;">Cảm ơn và hẹn gặp lại!</div>
</div>
